function update(dt){if(!running)return;game.elapsed+=dt;game.roomTime+=dt;game.attackCD=Math.max(0,game.attackCD-dt);game.dashCD=Math.max(0,game.dashCD-dt);game.invuln=Math.max(0,game.invuln-dt);game.attackWave=Math.max(0,game.attackWave-dt);let dx=(keys.KeyD||keys.ArrowRight||keys.KeyL||touchDir.right?1:0)-(keys.KeyA||keys.ArrowLeft||keys.KeyJ||touchDir.left?1:0),dy=(keys.KeyS||keys.ArrowDown||keys.KeyK||touchDir.down?1:0)-(keys.KeyW||keys.ArrowUp||keys.KeyI||touchDir.up?1:0);let d=Math.hypot(dx,dy);if(d){dx/=d;dy/=d;game.faceX=dx;game.faceY=dy;game.px=clamp(game.px+dx*game.speed*dt,56,W-56);game.py=clamp(game.py+dy*game.speed*dt,78,H-56)}
 game.spawnTimer-=dt;if(game.spawnTimer<=0&&game.enemies.length<6+game.floor){spawnEnemy(Math.random()<.2?'heavy':'drone');game.spawnTimer=Math.max(1.5,4-game.floor*.18)}
 for(const e of [...game.enemies]){e.flash=Math.max(0,e.flash-dt);e.phase+=dt;let ax=game.px-e.x,ay=game.py-e.y,dist=Math.hypot(ax,ay)||1;if(dist>e.r+23){e.x+=ax/dist*e.speed*dt;e.y+=ay/dist*e.speed*dt}e.cd-=dt;if(e.type==='warden'&&e.cd<=0&&dist>95){game.projectiles.push({x:e.x,y:e.y,vx:ax/dist*185,vy:ay/dist*185,r:6,life:3});e.cd=1.3;spawnBurst(e.x,e.y,'#fa6f67',3)}if(dist<e.r+17&&game.invuln<=0&&e.cd<=0){game.hp-=e.damage;game.invuln=.7;e.cd=.72;shake=8;spawnBurst(game.px,game.py,'#fa6f67',8);floatText(game.px,game.py-24,`-${e.damage}`,'#fa8179');if(game.hp<=0){game.hp=0;finish(false)}}}
 for(const p of [...game.projectiles]){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(Math.hypot(p.x-game.px,p.y-game.py)<p.r+12&&game.invuln<=0){game.hp-=12;game.invuln=.55;game.projectiles=game.projectiles.filter(q=>q!==p);spawnBurst(game.px,game.py,'#fa6f67',8);shake=7;if(game.hp<=0){game.hp=0;finish(false)}}else if(p.life<=0)game.projectiles=game.projectiles.filter(q=>q!==p)}
 for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt}particles=particles.filter(p=>p.life>0);for(const f of floaters){f.y-=25*dt;f.life-=dt}floaters=floaters.filter(f=>f.life>0);if(game.enemies.length===0&&game.spawnTimer>0&&game.roomTime>2){game.floor++;if(game.floor>6){finish(true);return}spawnFloor()}if(Math.floor(game.elapsed)%2===0)updateHUD()}
function finish(win){running=false;screen='end';$('#endScreen').classList.remove('hidden');$('#endEyebrow').textContent=win?'◇ NOYAU STELLARIS — NEUTRALISÉ':'◇ SIGNAL PERDU — SUJET ÉLIMINÉ';$('#endTitle').innerHTML=win?'LE VIVANT<br><em>PERSISTE.</em>':'FIN DE<br><em>TRANSMISSION.</em>';$('#endText').textContent=win?'Le cœur mécanique s’éteint. La spore s’enracine dans ses circuits : une nouvelle forme de vie vient de naître.':'Les machines ont repris le secteur. Mais chaque fragment absorbé a appris quelque chose à la prochaine génération.';$('#endStats').textContent=`${game.kills} ROBOTS DÉTRUITS  /  ${game.level} ÉVOLUTIONS  /  ÉTAGE ${Math.min(game.floor,6)}`}
function rounded(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function draw(){ctx.setTransform(canvas.clientWidth/W,0,0,canvas.clientHeight/H,0,0);ctx.clearRect(0,0,W,H);ctx.fillStyle='#0b1215';ctx.fillRect(0,0,W,H);
 // tiled metal floor
 for(let y=0;y<H;y+=48)for(let x=0;x<W;x+=48){ctx.fillStyle=((x/48+y/48)%2?'#10191c':'#111b1e');ctx.fillRect(x+1,y+1,46,46);ctx.strokeStyle='#1b292b';ctx.lineWidth=1;ctx.strokeRect(x+1.5,y+1.5,45,45)}
 // floor traces
 ctx.save();ctx.globalAlpha=.32;ctx.strokeStyle='#31483e';ctx.lineWidth=1;for(let i=0;i<8;i++){let x=100+i*160;ctx.beginPath();ctx.moveTo(x,70);ctx.lineTo(x,82);ctx.lineTo(x+25,82);ctx.stroke();ctx.fillStyle='#c8f169';ctx.fillRect(x-2,68,4,4)}ctx.restore();
 // room edge and corners
 ctx.strokeStyle='#32413f';ctx.lineWidth=5;ctx.strokeRect(39,45,W-78,H-90);ctx.lineWidth=1;ctx.strokeStyle='#6b8758';for(const [x,y,sx,sy] of [[40,46,1,1],[W-40,46,-1,1],[40,H-46,1,-1],[W-40,H-46,-1,-1]]){ctx.beginPath();ctx.moveTo(x,y+sy*24);ctx.lineTo(x,y);ctx.lineTo(x+sx*24,y);ctx.stroke()}
 // small consoles
 for(const [x,y] of [[95,114],[W-95,114],[95,H-114],[W-95,H-114]]){ctx.fillStyle='#172426';rounded(x-22,y-13,44,26,3);ctx.fill();ctx.strokeStyle='#344642';ctx.stroke();ctx.fillStyle='#76b778';ctx.fillRect(x-12,y-3,24,2);ctx.fillStyle='#384943';ctx.fillRect(x-12,y+3,15,2)}
 if(!game){drawCreature(W/2,H/2,0);return}ctx.save();if(shake>0){ctx.translate(rand(-shake,shake),rand(-shake,shake));shake=Math.max(0,shake-.7)}
 // floating sparks
 for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r*clamp(p.life/p.max,.2,1),0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
 // attack ring
 if(game.attackWave>0){ctx.globalAlpha=game.attackWave/.2*.4;ctx.strokeStyle='#c8f169';ctx.lineWidth=3;ctx.beginPath();ctx.arc(game.px,game.py,game.range*(1-game.attackWave/.2),0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}
 for(const p of game.projectiles){ctx.shadowBlur=14;ctx.shadowColor='#fb635e';ctx.fillStyle='#fa756a';ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.beginPath();ctx.arc(p.x,p.y,p.r+4,0,Math.PI*2);ctx.strokeStyle='#fa756a55';ctx.stroke()}
 for(const e of game.enemies)drawEnemy(e);drawCreature(game.px,game.py,game.elapsed);
 for(const f of floaters){ctx.globalAlpha=clamp(f.life,0,1);ctx.font='bold 12px "DM Mono"';ctx.textAlign='center';ctx.fillStyle=f.color;ctx.fillText(f.text,f.x,f.y)}ctx.globalAlpha=1;ctx.restore();
 // vignette
 let grad=ctx.createRadialGradient(W/2,H/2,180,W/2,H/2,700);grad.addColorStop(0,'#0000');grad.addColorStop(1,'#03080777');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H)
}
function drawCreature(x,y,t){ctx.save();ctx.translate(x,y);let bob=Math.sin(t*5)*2;ctx.translate(0,bob);ctx.shadowBlur=24;ctx.shadowColor='#62e8cb';ctx.fillStyle='#62e8cb';ctx.beginPath();ctx.ellipse(0,0,17,20,Math.sin(t*1.7)*.12,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#b9ffdd';ctx.beginPath();ctx.ellipse(0,-3,9,12,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#132323';ctx.beginPath();ctx.arc(4,-5,2.1,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#8affce';ctx.lineWidth=2;for(let i=0;i<4;i++){let a=t*2+i*Math.PI/2;ctx.beginPath();ctx.moveTo(Math.cos(a)*13,Math.sin(a)*15);ctx.quadraticCurveTo(Math.cos(a)*24,Math.sin(a)*24+Math.sin(t*4+i)*3,Math.cos(a)*25,Math.sin(a)*27);ctx.stroke()}ctx.strokeStyle='#d2ff90';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,25,0,Math.PI*2);ctx.stroke();ctx.restore()}
function drawEnemy(e){ctx.save();ctx.translate(e.x,e.y);let boss=e.type==='warden',heavy=e.type==='heavy',bob=Math.sin(e.phase*4)*2;ctx.translate(0,bob);ctx.shadowBlur=boss?18:8;ctx.shadowColor=e.flash?'#fff':'#fa6f67';let w=boss?26:heavy?20:16,h=boss?24:heavy?21:17;ctx.fillStyle=e.flash?'#fff':boss?'#b84c48':heavy?'#9b4542':'#bd5951';rounded(-w,-h,w*2,h*2,heavy?4:6);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#452f32';rounded(-w+4,-h+5,w*2-8,h*2-10,3);ctx.fill();ctx.fillStyle='#ffb26d';ctx.fillRect(-w+5,-4,w*2-10,4);ctx.fillStyle='#f9c67c';ctx.fillRect(-w+5,-4,4,4);ctx.strokeStyle='#e7786d';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-w,0);ctx.lineTo(-w-5,5);ctx.moveTo(w,0);ctx.lineTo(w+5,5);ctx.stroke();if(boss){ctx.strokeStyle='#fa8275';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,w+7,0,Math.PI*2);ctx.stroke()}
 let bw=boss?48:heavy?40:32;ctx.fillStyle='#352b2c';ctx.fillRect(-bw/2,-h-12,bw,3);ctx.fillStyle='#fa6f67';ctx.fillRect(-bw/2,-h-12,bw*clamp(e.hp/e.maxHp,0,1),3);ctx.restore()}
function frame(ts){let dt=Math.min(.033,(ts-last)/1000||0);last=ts;update(dt);draw();requestAnimationFrame(frame)}requestAnimationFrame(frame);
$('#startBtn').addEventListener('click',begin);$('#restartBtn').addEventListener('click',begin);document.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Space'||e.code==='Enter')attack();if(e.code==='ShiftLeft'||e.code==='ShiftRight')dash();if(screen==='start'&&e.code==='Enter')begin()});document.addEventListener('keyup',e=>keys[e.code]=false);canvas.addEventListener('pointerdown',e=>{if(screen==='play')attack()});document.querySelectorAll('[data-dir]').forEach(b=>{const dir=b.dataset.dir;b.addEventListener('pointerdown',e=>{e.preventDefault();touchDir[dir]=true;b.setPointerCapture(e.pointerId)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>touchDir[dir]=false)});$('#attackTouch').addEventListener('pointerdown',e=>{e.preventDefault();attack();let timer=setInterval(()=>{if(!touchDir.attack){clearInterval(timer);return}attack()},100);touchDir.attack=true});for(const ev of ['pointerup','pointercancel','lostpointercapture'])$('#attackTouch').addEventListener(ev,()=>touchDir.attack=false);window.addEventListener('blur',()=>{keys={};touchDir={}});
</script></body></html>

