 function floatText(x,y,text,color='#c8f169'){floaters.push({x,y,text,color,life:1})}
 function attack(){if(!running||game.attackCD>0)return;game.attackCD=game.attackRate;game.attackWave=.2;let target=null,best=Infinity;for(const e of game.enemies){let d=Math.hypot(e.x-game.px,e.y-game.py);if(d<game.range+e.r&&d<best){best=d;target=e}}if(target){let dx=target.x-game.px,dy=target.y-game.py,d=Math.hypot(dx,dy)||1;target.hp-=game.damage;target.flash=.12;target.x+=dx/d*(game.knockback||24);target.y+=dy/d*(game.knockback||24);spawnBurst(target.x,target.y,'#c8f169',5);floatText(target.x,target.y-16,`-${Math.round(game.damage)}`);if(target.hp<=0)killEnemy(target)}else spawnBurst(game.px+game.faceX*35,game.py+game.faceY*35,'#62e8cb',3)}
